// Picks ONE topic per run: the earliest planned_date among the rows that
// have not been sent to PinBridge yet. Rows with no planned_date go out now.
const cfg = $('Set Configuration Fields').first().json;
const zone = $now.zoneName; // Workflow settings -> Timezone
const [defaultHour, defaultMinute] = String(cfg.default_publish_time || '09:00')
  .split(':')
  .map(Number);

for (const key of ['sheet_url', 'pinterest_account_id', 'default_board_id']) {
  if (String(cfg[key] || '').includes('PASTE_')) {
    throw new Error(`Fill in ${key} in "Set Configuration Fields" first.`);
  }
}

const text = (value) => String(value ?? '').trim();

function plannedDate(value, rowNumber) {
  if (text(value) === '') return $now;

  // A real date cell arrives as a Google Sheets serial number:
  // whole days since 1899-12-30, with the time of day as the fraction.
  if (typeof value === 'number') {
    const days = Math.floor(value);
    const seconds = Math.round((value - days) * 86400);
    const day = DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone }).plus({ days });
    return seconds === 0
      ? day.set({ hour: defaultHour, minute: defaultMinute })
      : day.set({ hour: Math.floor(seconds / 3600), minute: Math.floor(seconds / 60) % 60, second: seconds % 60 });
  }

  // A text cell: 2026-10-01, 2026-10-01 09:30, or full ISO with an offset.
  const raw = text(value);
  let date = DateTime.fromISO(raw.replace(' ', 'T'), { zone, setZone: true });
  if (!date.isValid) {
    throw new Error(`Row ${rowNumber}: planned_date "${raw}" is not a date. Use 2026-10-01 or 2026-10-01 09:30.`);
  }
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
    date = date.set({ hour: defaultHour, minute: defaultMinute });
  }
  return date;
}

const pending = $input.all()
  .map((item, index) => ({ row: item.json, index }))
  .filter(({ row }) =>
    text(row.topic) !== '' &&
    text(row.published_at) === '' &&
    text(row.pinbridge_pin_id) === '' &&
    text(row.pinbridge_schedule_id) === ''
  )
  .map((entry) => ({ ...entry, when: plannedDate(entry.row.planned_date, entry.row.row_number) }))
  .sort((a, b) => a.when.toMillis() - b.when.toMillis());

if (!pending.length) {
  return []; // Every topic is already published or scheduled.
}

const { row, index, when } = pending[0];

// Sheets turns a long board ID typed as a number into a rounded float.
if (typeof row.board_id === 'number') {
  throw new Error(`Row ${row.row_number}: format the board_id column as plain text (Format -> Number -> Plain text), then paste the ID again.`);
}

// Stable per topic, so a re-run after a failed sheet update cannot publish twice.
let hash = 5381;
for (const ch of `${row.row_number}|${text(row.topic)}`) hash = ((hash * 33) ^ ch.charCodeAt(0)) >>> 0;

return [{
  json: {
    row_number: row.row_number,
    topic: text(row.topic),
    context: text(row.context),
    link_url: text(row.link_url),
    image_url: text(row.image_url),
    board_id: text(row.board_id) || text(cfg.default_board_id),
    pinterest_account_id: text(cfg.pinterest_account_id),
    run_at: when.toISO({ suppressMilliseconds: true }),
    idempotency_key: `topic-row-${row.row_number}-${hash.toString(36)}`
  },
  pairedItem: { item: index }
}];

