// Merge the AI copy onto the topic so every later step has one item to read.
const topic = $('Select Next Topic by Date').first().json;
const reply = $input.first().json;

// Without an output parser the chain returns the model's JSON as text.
// With one, it arrives under "output". Accept both.
let copy = reply.output ?? reply.text ?? (reply.message && reply.message.content) ?? reply;
if (typeof copy === 'string') {
  const raw = copy.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { copy = JSON.parse(raw); } catch (e) { copy = {}; }
}
if (copy && typeof copy.output === 'object') {
  copy = copy.output; // the prompt asks the model to wrap its answer in "output"
}

if (!copy || !copy.title) {
  throw new Error(`No pin copy came back for "${topic.topic}". Check the model output.`);
}
if (!topic.image_url && !String(copy.creative_description || '').trim()) {
  throw new Error(`No creative_description came back for "${topic.topic}", so there is nothing to generate the image from.`);
}

return [{
  json: {
    ...topic,
    title: String(copy.title).slice(0, 100),
    description: String(copy.description || '').slice(0, 800),
    alt_text: String(copy.alt_text || '').slice(0, 500),
    creative_description: String(copy.creative_description || '').trim()
  },
  pairedItem: { item: 0 }
}];

// Put the uploaded asset back on the pin and decide whether it goes out
// now or waits for its planned date. Anything under two minutes away is
// published straight away (PinBridge only schedules times in the future).
const pin = $('Merge Topic and Description').first().json;
const asset = $input.first().json;

if (!asset.id) {
  throw new Error('PinBridge did not return an asset ID for the uploaded image.');
}

const runAt = DateTime.fromISO(pin.run_at);

return [{
  json: {
    ...pin,
    asset_id: asset.id,
    asset_url: asset.publicUrl || '',
    image_source: pin.image_url ? 'sheet' : 'generated',
    mode: runAt > $now.plus({ minutes: 2 }) ? 'schedule' : 'publish'
  },
  pairedItem: { item: 0 }
}];

// A pin published straight away is stored on its row by pin ID. A scheduled
// pin only gets a pin ID when its schedule fires, and PinBridge gives that
// pin the idempotency key "schedule_<schedule ID>", which we match instead.
const pin = $('Retrieve Pin Details').first().json;
const event = $('Set Confirmation Fields').first().json.body;
const scheduleKey = String(pin.idempotencyKey || '');
const rows = $input.all().map((item) => item.json);

const index = rows.findIndex((row) =>
  (row.pinbridge_pin_id && String(row.pinbridge_pin_id) === pin.id) ||
  (row.pinbridge_schedule_id && scheduleKey === `schedule_${row.pinbridge_schedule_id}`)
);

// Not a pin from this topic list, or a webhook retry we already recorded.
if (index === -1 || String(rows[index].confirmed_at ?? '').trim() !== '') {
  return [];
}

const row = rows[index];
return [{
  json: {
    row_number: row.row_number,
    status: 'live',
    confirmed_at: event.published_at || pin.publishedAt || $now.toISO(),
    pinbridge_pin_id: pin.id,
    pinterest_url: pin.pinterestPinId ? `https://www.pinterest.com/pin/${pin.pinterestPinId}/` : '',
    pin_title: row.pin_title || pin.title
  },
  pairedItem: { item: index }
}];
